const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const CHARACTER_API='https://genshin-db-api.vercel.app/api/v5/characters?query=names&matchCategories=true&verboseCategories=true';
const CHARACTER_CACHE='stygian-character-catalog-v1',CHARACTER_CACHE_TTL=6*60*60*1000,PAGE_SIZE=24;
const imageHosts=new Set(['act-webstatic.hoyoverse.com','act-upload.hoyoverse.com','bbs.hoyolab.com','upload-static.hoyoverse.com','upload-os-bbs.mihoyo.com']);
let db,promise,ctx,dialog,kind,slot,query='',element='',weapon='',rarity='',page=0,catalogStatus='Using the bundled character list while checking Genshin-DB…';
function safeImage(value){try{const u=new URL(value);return u.protocol==='https:'&&imageHosts.has(u.hostname)?u.href:''}catch{return ''}}
function normalizeCharacters(rows){if(!Array.isArray(rows)||rows.length<50)throw Error('Character API returned an incomplete catalog.');const out=rows.map(x=>({id:Number(x.id),name:String(x.name||''),element:String(x.elementText||''),weaponType:String(x.weaponText||''),rarity:Number(x.rarity),image:safeImage(x.images?.hoyowiki_icon)||safeImage(x.images?.mihoyo_icon),version:String(x.version||'')})).filter(x=>x.id&&x.name&&['None','Anemo','Cryo','Dendro','Electro','Geo','Hydro','Pyro'].includes(x.element)&&['Sword','Claymore','Polearm','Bow','Catalyst'].includes(x.weaponType)&&[4,5].includes(x.rarity)).sort((a,b)=>a.name.localeCompare(b.name));if(out.length<50)throw Error('Character API returned invalid records.');return out}
function versionOf(rows){return rows.map(x=>x.version).filter(Boolean).sort((a,b)=>a.localeCompare(b,undefined,{numeric:true})).at(-1)||''}
function applyCharacterRows(rows,status){db.characters=rows;catalogStatus=status}
async function refreshCharacters(){try{let cached;try{cached=JSON.parse(localStorage.getItem(CHARACTER_CACHE)||'null')}catch{}if(cached?.updatedAt&&Date.now()-cached.updatedAt<CHARACTER_CACHE_TTL){const rows=normalizeCharacters(cached.characters);applyCharacterRows(rows,`Live catalog · Genshin-DB v${esc(cached.version||versionOf(rows))} · checked ${new Date(cached.updatedAt).toLocaleString()}.`);return true}
const response=await fetch(CHARACTER_API,{signal:AbortSignal.timeout(12000)});if(!response.ok)throw Error('Character API unavailable');const payload=await response.json(),rows=normalizeCharacters(payload),updatedAt=Date.now(),version=versionOf(rows);applyCharacterRows(rows,`Live catalog · Genshin-DB v${esc(version||'current')} · checked just now.`);try{localStorage.setItem(CHARACTER_CACHE,JSON.stringify({updatedAt,version,characters:rows}))}catch{}return true}catch{catalogStatus='Live character API unavailable · showing the bundled catalog.';return false}}
async function catalog(){if(db)return db;if(!promise)promise=fetch('./game-catalog.json?v=8').then(r=>{if(!r.ok)throw Error('Catalog unavailable');return r.json()}).then(x=>db=x).catch(e=>{promise=null;throw e});return promise}
export function setupBuilder(context){ctx=context;document.addEventListener('click',e=>{const b=e.target.closest('[data-picker],[data-library],[data-compare],[data-akasha],[data-akasha-profiles],[data-member]');if(!b)return;if(b.dataset.compare!==undefined)openCompare();else if(b.dataset.library!==undefined)openLibrary();else if(b.dataset.akasha!==undefined)openAkasha();else if(b.dataset.akashaProfiles!==undefined)openAkashaProfiles();else if(b.dataset.member!==undefined){const profiles=profilesFor(ctx.character().name);if(profiles.length>1)openProfileChooser(profiles)}else openPicker(b.dataset.picker,b.dataset.slot||'set')})}
function modal(title){dialog?.remove();dialog=document.createElement('dialog');dialog.className='builder-dialog';dialog.setAttribute('aria-label',title);dialog.innerHTML=`<div class="dialog-head"><h2>${esc(title)}</h2><button class="dialog-close" aria-label="Close dialog">×</button></div><div class="dialog-body"></div>`;document.body.append(dialog);dialog.querySelector('.dialog-close').onclick=()=>dialog.close();dialog.addEventListener('click',e=>{if(e.target===dialog)dialog.close()});dialog.addEventListener('close',()=>dialog.remove());dialog.showModal();return dialog.querySelector('.dialog-body')}
function profilesFor(name){return (ctx.state().akashaProfiles||[]).filter(x=>ctx.normalize(x.character)===ctx.normalize(name)).sort((a,b)=>String(b.createdAt).localeCompare(String(a.createdAt)))}
function openAkasha(){const body=modal('Import Akasha CV build');body.innerHTML=`<p>Choose an Akasha CV character-card PNG. OCR runs in this browser; the screenshot is not uploaded. Review and correct the recognized values before saving. The parsed total stats are used for calculations because OCR cannot reliably read every artifact substat icon.</p><label class="field">Akasha CV PNG<input id="akasha-file" type="file" accept="image/png,.png"></label><p class="inline-note" id="akasha-status" role="status" aria-live="polite">The first OCR run downloads the Tesseract engine and English data to your browser cache.</p><div id="akasha-review"></div>`;const file=body.querySelector('#akasha-file'),status=body.querySelector('#akasha-status'),review=body.querySelector('#akasha-review');file.onchange=async()=>{const selected=file.files?.[0];if(!selected)return;status.textContent='Reading screenshot locally…';review.innerHTML='';file.disabled=true;try{const raw=await readAkashaPng(selected,n=>{status.textContent=`Reading screenshot locally… ${n}%`});const cat=await catalog();await refreshCharacters();const data=parseAkashaText(raw,cat);data.catalog=cat;if(!body.isConnected)return;status.textContent='Review every detected field. Unrecognized values are left blank.';drawAkashaReview(review,data,selected.name)}catch(error){status.textContent=error.message||'Could not read this screenshot.'}finally{if(file.isConnected)file.disabled=false}}
}
function drawAkashaReview(root,data,fileName){
  const chars=data.catalog?.characters||[];
  root.innerHTML=`<div class="akasha-review"><div class="picker-filters"><label class="field">Character<select id="akasha-character"><option value="">Choose character</option>${chars.map(x=>`<option value="${esc(x.name)}" ${x.name===data.character?'selected':''}>${esc(x.name)}</option>`).join('')}</select></label><label class="field">Weapon<input id="akasha-weapon" value="${esc(data.weapon)}"></label><label class="field">Artifact set<input id="akasha-set" value="${esc(data.set)}"></label><label class="field">Build label<input id="akasha-label" maxlength="70" value="${esc(data.character?`${data.character} · ${data.weapon||'Akasha build'}`:'Akasha build')}"></label><label class="field">Character level<input id="akasha-level" type="number" min="1" max="90" value="${data.level||90}"></label><label class="field">Weapon level<input id="akasha-weapon-level" type="number" min="1" max="90" value="${data.weaponLevel||90}"></label><label class="field">Refinement<input id="akasha-refine" type="number" min="1" max="5" value="${data.refine||1}"></label>${[['hp','Max HP'],['atk','ATK'],['def','DEF'],['em','Elemental mastery'],['cr','CRIT rate %'],['cd','CRIT damage %'],['er','Energy recharge %'],['dmg','Elemental DMG bonus %']].map(([key,label])=>`<label class="field">${label}<input data-akasha-stat="${key}" type="number" step="any" min="0" value="${data.stats[key]??''}"></label>`).join('')}</div><div class="button-row"><button class="primary" id="akasha-save">Save profile & equip now</button><button id="akasha-save-only">Save profile</button></div><details class="akasha-raw"><summary>OCR text · ${esc(fileName)}</summary><pre>${esc(data.raw)}</pre></details></div>`;
  root.querySelector('#akasha-character').onchange=e=>{const opt=chars.find(x=>x.name===e.target.value);if(opt)root.dataset.element=opt.element||''};
  const save=(apply)=>{const character=root.querySelector('#akasha-character').value;if(!character){root.querySelector('#akasha-character').focus();return}const stats={};for(const input of root.querySelectorAll('[data-akasha-stat]'))if(input.value.trim()!==''&&Number.isFinite(Number(input.value)))stats[input.dataset.akashaStat]=Number(input.value);const entry={id:crypto.randomUUID(),character,element:chars.find(x=>x.name===character)?.element||root.dataset.element||'',weapon:root.querySelector('#akasha-weapon').value.trim(),set:root.querySelector('#akasha-set').value.trim(),label:root.querySelector('#akasha-label').value.trim()||`${character} · Akasha build`,level:Number(root.querySelector('#akasha-level').value)||90,weaponLevel:Number(root.querySelector('#akasha-weapon-level').value)||90,refine:Number(root.querySelector('#akasha-refine').value)||1,stats,createdAt:new Date().toISOString(),source:'Akasha CV PNG'};const state=ctx.state();state.akashaProfiles??=[];state.akashaProfiles.push(entry);if(apply)ctx.applyAkasha(entry);if(!ctx.persist()){state.akashaProfiles.pop();return}ctx.render();dialog.close();ctx.toast(apply?'Akasha build saved and equipped.':'Akasha profile saved in this browser.')};
  root.querySelector('#akasha-save').onclick=()=>save(true);root.querySelector('#akasha-save-only').onclick=()=>save(false);
}
function openAkashaProfiles(){const body=modal('Saved Akasha builds');let selected='';const draw=()=>{const list=ctx.state().akashaProfiles||[];if(!selected||!list.some(x=>x.id===selected))selected=profilesFor(ctx.character().name)[0]?.id||list[0]?.id||'';body.innerHTML=`<p>Profiles are stored in this browser. Select one to equip it in the current character slot. Screenshots themselves are not saved.</p><div class="akasha-profiles">${list.length?list.map(x=>`<button class="akasha-profile ${x.id===selected?'active':''}" data-profile-pick="${esc(x.id)}"><strong>${esc(x.label)}</strong><small>${esc(x.character)} · Lv. ${x.level} · ${esc(x.weapon||'Weapon not recognized')} · ${esc(x.set||'Set not recognized')}</small><small>${[['ATK',x.stats.atk],['CRIT Rate',x.stats.cr],['CRIT DMG',x.stats.cd]].filter(([,v])=>v!==undefined).map(([k,v])=>`${k} ${v}`).join(' · ')}</small></button>`).join(''):'<div class="empty">No Akasha profiles yet. Import a PNG to save your first build.</div>'}</div><div class="button-row"><button class="primary" id="akasha-equip" ${selected?'':'disabled'}>Equip selected in current slot</button><button data-akasha>Import another PNG</button><button id="akasha-delete" ${selected?'':'disabled'}>Delete selected</button></div>`;body.querySelector('.akasha-profiles').onclick=e=>{const b=e.target.closest('[data-profile-pick]');if(b){selected=b.dataset.profilePick;draw()}};body.querySelector('#akasha-equip').onclick=()=>{const p=(ctx.state().akashaProfiles||[]).find(x=>x.id===selected);if(!p)return;ctx.applyAkasha(p);ctx.persist();ctx.render();dialog.close();ctx.toast('Akasha build equipped.')};body.querySelector('#akasha-delete').onclick=()=>{const p=(ctx.state().akashaProfiles||[]).find(x=>x.id===selected);if(!p||!confirm(`Delete ${p.label}?`))return;ctx.state().akashaProfiles=ctx.state().akashaProfiles.filter(x=>x.id!==selected);ctx.persist();selected='';draw()}};draw()}
function openProfileChooser(profiles){const body=modal(`Choose ${profiles[0].character} build`);let chosen=profiles[0].id;const draw=()=>{body.innerHTML=`<p>This character has multiple saved Akasha profiles. Select the build you want, then confirm to apply it to this slot.</p><div class="akasha-profiles">${profiles.map(p=>`<button class="akasha-profile ${chosen===p.id?'active':''}" data-profile-pick="${esc(p.id)}"><strong>${esc(p.label)}</strong><small>Lv. ${p.level} · ${esc(p.weapon||'Weapon not recognized')} · ${esc(p.set||'Set not recognized')}</small><small>${[['ATK',p.stats.atk],['CRIT Rate',p.stats.cr],['CRIT DMG',p.stats.cd]].filter(([,v])=>v!==undefined).map(([k,v])=>`${k} ${v}`).join(' · ')}</small></button>`).join('')}</div><button class="primary" id="akasha-equip">Confirm and equip selected build</button>`;body.querySelector('.akasha-profiles').onclick=e=>{const b=e.target.closest('[data-profile-pick]');if(b){chosen=b.dataset.profilePick;draw()}};body.querySelector('#akasha-equip').onclick=()=>{const p=profiles.find(x=>x.id===chosen);if(!p)return;ctx.applyAkasha(p);ctx.persist();ctx.render();dialog.close();ctx.toast('Akasha build equipped.')}};draw()}
async function openPicker(type,field){kind=type;slot=field;query=element=rarity='';weapon='';page=0;catalogStatus='Using the bundled character list while checking Genshin-DB…';const body=modal(type==='characters'?'Choose a character':type==='weapons'?'Choose a weapon':'Choose an artifact set');body.innerHTML='<p role="status">Loading catalog…</p>';try{const data=await catalog();if(!body.isConnected)return;const c=ctx.character();if(type==='weapons')weapon=data.characters.find(x=>ctx.normalize(x.name)===ctx.normalize(ctx.resolve('characters',c.name)))?.weaponType||'';const rarityOptions=type==='characters'?['5','4']:type==='weapons'?['5','4','3','2','1']:['5','4','3'];body.innerHTML=`<p>Choose a ${type==='characters'?'character for the selected slot. New characters start with example stats; configure their build after selecting.':type==='weapons'?'weapon. Review its numerical stats and passive effects after equipping.':'set. Choose the piece configuration in the Artifacts tab.'}</p><div class="picker-filters"><label class="field">Search by name<input type="search" id="catalog-search" placeholder="Start typing…" autocomplete="off"></label>${type==='characters'?select('Element','catalog-element',['Anemo','Cryo','Dendro','Electro','Geo','Hydro','Pyro','None']):''}${type!=='artifacts'?select('Weapon type','catalog-weapon',['Sword','Claymore','Polearm','Bow','Catalyst'],weapon):''}${select('Rarity','catalog-rarity',rarityOptions)}</div><p id="catalog-count" role="status" aria-live="polite"></p>${type==='characters'?'<p id="catalog-source" class="catalog-source" role="status" aria-live="polite"></p>':''}<div class="picker-results"></div>`;
const box=body.querySelector('.picker-results');body.querySelector('#catalog-search').oninput=e=>{query=e.target.value;page=0;results()};for(const [id,key]of [['catalog-element','element'],['catalog-weapon','weapon'],['catalog-rarity','rarity']]){const el=body.querySelector('#'+id);if(el)el.onchange=e=>{if(key==='element')element=e.target.value;if(key==='weapon')weapon=e.target.value;if(key==='rarity')rarity=e.target.value;page=0;results()}}box.onclick=e=>{const nav=e.target.closest('[data-page]');if(nav){page=Number(nav.dataset.page);results();box.scrollTop=0;return}const b=e.target.closest('[data-catalog-id]');if(!b)return;const item=db[kind].find(x=>String(x.id)===b.dataset.catalogId);if(!item)return;ctx.choose(kind,item,slot);dialog.close()};results();body.querySelector('#catalog-search').focus();if(type==='characters'){refreshCharacters().then(()=>{if(!body.isConnected)return;body.querySelector('#catalog-source').textContent=catalogStatus;results()});body.querySelector('#catalog-source').textContent=catalogStatus}}catch{if(body.isConnected)body.innerHTML='<p>Could not load the catalog. Close this window and try again.</p>'}}
function select(label,id,items,value=''){return `<label class="field">${label}<select id="${id}"><option value="">All</option>${items.map(x=>`<option ${x===value?'selected':''} value="${x}">${x}${label==='Rarity'?'★':''}</option>`).join('')}</select></label>`}
function results(){if(!db||!kind||!dialog?.isConnected)return;const list=db[kind].filter(x=>ctx.normalize(x.name).includes(ctx.normalize(query))&&(!element||x.element===element)&&(!weapon||x.weaponType===weapon)&&(!rarity||String(x.rarity)===rarity));const box=dialog.querySelector('.picker-results'),count=dialog.querySelector('#catalog-count'),pages=Math.max(1,Math.ceil(list.length/PAGE_SIZE));page=Math.max(0,Math.min(page,pages-1));const start=page*PAGE_SIZE,visible=list.slice(start,start+PAGE_SIZE);count.textContent=list.length?`Showing ${start+1}–${Math.min(start+PAGE_SIZE,list.length)} of ${list.length} ${kind} · Page ${page+1} of ${pages}`:`0 matching ${kind} · Page 1 of 1`;const cards=visible.map(x=>{const duplicate=kind==='characters'&&ctx.team().chars.some((c,i)=>i!==ctx.member()&&ctx.normalize(ctx.resolve('characters',c.name))===ctx.normalize(x.name));return `<button class="catalog-item" data-catalog-id="${x.id}" ${duplicate?'disabled':''}><span class="catalog-avatar">${x.image?`<img src="${esc(ctx.localImage(kind,x.name)||x.image)}" alt="" width="64" height="64" loading="lazy">`:'✧'}</span><span><strong>${esc(x.name)}</strong><small>${[x.element,x.weaponType,x.rarity+'★'].filter(Boolean).map(esc).join(' · ')}${duplicate?' · Already in team':''}</small></span></button>`}).join('');const pager=list.length>PAGE_SIZE?`<nav class="catalog-pagination" aria-label="Catalog pages"><button type="button" data-page="${page-1}" ${page===0?'disabled':''}>← Previous</button><span>Page ${page+1} of ${pages}</span><button type="button" data-page="${page+1}" ${page===pages-1?'disabled':''}>Next →</button></nav>`:'';box.innerHTML=(cards||'<div class="empty">No matches. Try another name or clear your filters.</div>')+pager;box.querySelectorAll('img').forEach(img=>img.onerror=()=>{img.hidden=true;img.parentElement.textContent='✧'})}
function openLibrary(){const body=modal('Saved teams');drawLibrary(body)}
function drawLibrary(body){const state=ctx.state(),list=state.savedTeams||[];body.innerHTML=`<p>Save a named copy of the current battle, including all four builds, equipment, buffs, rotation and enemy settings. Stored in this browser. Export builds to back up your library.</p><div class="save-team-form"><label class="field">Team name<input id="save-team-name" maxlength="80" value="${esc(ctx.team().title)}" placeholder="e.g. Mavuika Melt · boss build"></label><button class="primary" id="save-current-team">Save current team</button></div><div class="saved-list">${list.length?list.map(x=>`<section class="saved-team"><div><h3>${esc(x.name)}</h3><small>${esc(x.team.chars.map(c=>c.name).join(' · '))}</small><p>Saved ${new Date(x.updatedAt).toLocaleDateString()}</p></div><div class="button-row"><button data-load-team="${esc(x.id)}">Load into Battle ${state.selected+1}</button><button data-update-team="${esc(x.id)}">Overwrite</button><button data-rename-team="${esc(x.id)}">Rename</button><button data-delete-team="${esc(x.id)}">Delete</button></div></section>`).join(''):'<div class="empty">No saved teams yet. Save your first build above.</div>'}</div>`;body.querySelector('#save-current-team').onclick=()=>{const name=body.querySelector('#save-team-name').value.trim();if(!name){body.querySelector('#save-team-name').focus();return}state.savedTeams??=[];state.savedTeams.push({id:crypto.randomUUID(),name,updatedAt:new Date().toISOString(),team:structuredClone(ctx.team())});if(ctx.persist()){ctx.toast('Team saved.');drawLibrary(body)}};body.querySelector('.saved-list').onclick=e=>{const b=e.target.closest('button');if(!b)return;const id=Object.values(b.dataset)[0],entry=state.savedTeams.find(x=>x.id===id);if(!entry)return;if(b.dataset.loadTeam){if(!confirm('Replace the current battle with this saved team? Save your current team first if you want to keep it.'))return;state.teams[state.selected]=structuredClone(entry.team);state.member=0;ctx.persist();ctx.render();dialog.close();ctx.toast('Saved team loaded.')}else if(b.dataset.updateTeam){if(!confirm('Overwrite this saved team with the current battle build?'))return;entry.team=structuredClone(ctx.team());entry.updatedAt=new Date().toISOString();ctx.persist();drawLibrary(body)}else if(b.dataset.renameTeam){const name=prompt('Rename saved team',entry.name)?.trim();if(!name)return;entry.name=name.slice(0,80);ctx.persist();drawLibrary(body)}else if(b.dataset.deleteTeam){if(!confirm('Delete this saved team? The active battle will remain unchanged.'))return;state.savedTeams=state.savedTeams.filter(x=>x.id!==id);ctx.persist();drawLibrary(body)}}}
function openCompare(){const body=modal('Compare teams');let selected=['active-0','active-1','active-2'],metric='dps',common=true;const options=()=>[...ctx.state().teams.map((team,i)=>({id:'active-'+i,name:team.title,team})),...(ctx.state().savedTeams||[]).map(x=>({id:x.id,name:x.name,team:x.team}))];function draw(){const all=options(),picked=selected.map(id=>all.find(x=>x.id===id)).filter(Boolean);body.innerHTML=`<p>Compare up to three active or saved teams. Common enemy uses the current battle’s HP, level, resistance and downtime for every team.</p><div class="compare-pickers">${[0,1,2].map(i=>`<label class="field">Team ${i+1}<select data-compare-slot="${i}"><option value="">None</option>${all.map(x=>`<option value="${esc(x.id)}" ${selected[i]===x.id?'selected':''}>${esc(x.name)} ${x.id.startsWith('active-')?'(Battle '+(Number(x.id.slice(7))+1)+')':'(saved)'}</option>`).join('')}</select></label>`).join('')}</div><div class="picker-filters"><label class="field">Chart metric<select id="compare-metric"><option value="dps" ${metric==='dps'?'selected':''}>Team DPS · higher is better</option><option value="total" ${metric==='total'?'selected':''}>Damage per rotation</option><option value="time" ${metric==='time'?'selected':''}>Estimated clear seconds · lower is better</option></select></label><label><input type="checkbox" id="compare-common" ${common?'checked':''}> Use common enemy</label></div><div class="comparison-chart"></div><p class="inline-note">Damage assumes your entered rotation is executable. Check Energy for zero-start burst feasibility. Shield phases, special resources and timing are not simulated.</p>`;const rows=picked.map(x=>{const t=structuredClone(x.team);if(common)for(const key of ['hp','enemyLevel','res','resByElement','downtime'])t[key]=ctx.team()[key];return {...x,t,r:ctx.calc(t)}}),max=Math.max(1,...rows.map(x=>x.r[metric]||0));body.querySelector('.comparison-chart').innerHTML=rows.length?`<div role="img" aria-label="Team comparison bar chart">${rows.map(x=>`<div class="compare-bar"><strong>${esc(x.name)}</strong><div class="bar"><i style="width:${Math.max(0,(x.r[metric]||0)/max*100)}%"></i></div><span>${x.r[metric]===null?'—':Number(x.r[metric]).toLocaleString(undefined,{maximumFractionDigits:1})}</span></div>`).join('')}</div><div class="table-wrap"><table><thead><tr><th>Team</th><th>DPS</th><th>Rotation</th><th>Clear estimate</th><th>Enemy HP / RES</th></tr></thead><tbody>${rows.map(x=>`<tr><td><strong>${esc(x.name)}</strong><small class="roster-line">${esc(x.team.chars.map(c=>c.name).join(' · '))}</small></td><td>${Math.round(x.r.dps).toLocaleString()}</td><td>${x.t.rotation}s</td><td>${x.r.time===null?'—':x.r.time.toFixed(1)+'s'}</td><td>${x.t.hp.toLocaleString()} / ${x.t.res}%</td></tr>`).join('')}</tbody></table></div>`:'<p>Select at least one team to compare.</p>';body.querySelectorAll('[data-compare-slot]').forEach(el=>el.onchange=()=>{if(el.value&&selected.includes(el.value)&&selected[+el.dataset.compareSlot]!==el.value){ctx.toast('Choose a different team in each slot.');draw();return}selected[+el.dataset.compareSlot]=el.value;draw()});body.querySelector('#compare-metric').onchange=e=>{metric=e.target.value;draw()};body.querySelector('#compare-common').onchange=e=>{common=e.target.checked;draw()}}draw()}
import {readAkashaPng,parseAkashaText} from './akasha.mjs?v=1';
